import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Identify potential drivers based on effect size and significance
    effects = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'clinical':
            # For clinical features, use t-test effect size
            t_stat = feats.x[:, i].T @ feats.y / np.sqrt(np.var(feats.x[:, i]) * len(feats.y))
            p_val = 2 * (1 - stats.t.cdf(abs(t_stat), len(feats.y) - 1))
            if p_val < 0.05:
                effects.append((fid, abs(t_stat)))

    # Sort by effect size
    effects.sort(key=lambda x: x[1], reverse=True)

    # Select top candidates, avoiding near-duplicates
    selected = []
    excluded = set()

    for fid, _ in effects:
        if fid in excluded:
            continue

        # Check for correlations with already selected features
        is_duplicate = False
        for sel_fid in selected:
            col_a = feats.column(sel_fid)
            col_b = feats.column(fid)
            if abs(np.corrcoef(feats.x[:, col_a], feats.x[:, col_b])[0, 1]) >= 0.6:
                is_duplicate = True
                break

        if not is_duplicate:
            selected.append(fid)

        # Mark correlated features as excluded
        for other_fid in feats.ids:
            if other_fid == fid or other_fid in excluded:
                continue
            col_a = feats.column(fid)
            col_b = feats.column(other_fid)
            if abs(np.corrcoef(feats.x[:, col_a], feats.x[:, col_b])[0, 1]) >= 0.6:
                excluded.add(other_fid)

        if len(selected) >= MAX_DRIVERS:
            break

    # If no strong drivers found, return empty design
    if not selected:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Build logistic regression features
    columns = selected[:]
    products = []

    # Add interaction terms for top 3 drivers
    for i in range(min(3, len(selected))):
        for j in range(i+1, min(3, len(selected))):
            products.append((selected[i], selected[j]))

    # Compute weighted score using mutual information
    mi_scores = mutual_info_classif(feats.x[:, [feats.column(fid) for fid in selected]], feats.y)
    loadings = dict(zip(selected, mi_scores))

    return Design(
        drivers=tuple(selected),
        columns=tuple(columns),
        products=tuple(products),
        loadings=loadings
    )

